          </div>
          <button class="btn btn-primary" data-add="${index}">Add to bag</button>
        </div>
      </article>
    `).join("");

    productGrid.addEventListener("click", (event) => {
      const button = event.target.closest("[data-add]");
      if (!button) return;
      cartCount += 1;
      cartStatus.textContent = `Bag ${cartCount}`;
      button.textContent = "Added";
      button.disabled = true;
      button.style.opacity = "0.7";
    });

    const promoEnds = new Date(Date.now() + 1000 * 60 * 60 * 18 + 1000 * 60 * 42);
    const nodes = {
      days: document.getElementById("days"),
      hours: document.getElementById("hours"),
      mins: document.getElementById("mins"),
      secs: document.getElementById("secs")
    };

    function tick() {
      const diff = Math.max(promoEnds - new Date(), 0);
      const totalSecs = Math.floor(diff / 1000);
      const days = Math.floor(totalSecs / 86400);
      const hours = Math.floor((totalSecs % 86400) / 3600);
      const mins = Math.floor((totalSecs % 3600) / 60);
      const secs = totalSecs % 60;

      nodes.days.textContent = String(days).padStart(2, "0");
      nodes.hours.textContent = String(hours).padStart(2, "0");
      nodes.mins.textContent = String(mins).padStart(2, "0");
      nodes.secs.textContent = String(secs).padStart(2, "0");
    }

    tick();
    setInterval(tick, 1000);
